import React, { useState } from 'react';
import { Skeleton } from 'primereact/skeleton';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="skeleton-accessibility">Accessible Skeleton</label>
            <Skeleton 
                id="skeleton-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible Skeleton input"
                placeholder="Enter skeleton"
            />
        </div>
    );
}